<?php declare(strict_types=1);require_once __DIR__.'/config/database.php';header('Content-Type: application/xml; charset=utf-8');$base=((!empty($_SERVER['HTTPS'])&&$_SERVER['HTTPS']!=='off')?'https':'http').'://'.($_SERVER['HTTP_HOST']??'localhost').rtrim(dirname($_SERVER['SCRIPT_NAME']??'/'),'/');echo '<?xml version="1.0" encoding="UTF-8"?>';?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9"><?php foreach(['index.php','shop.php','faq.php','contact.php'] as $path):?><url><loc><?=htmlspecialchars($base.'/'.$path,ENT_XML1)?></loc></url><?php endforeach;$s=$pdo->query('SELECT slug,updated_at FROM products WHERE is_active=1');foreach($s as $p):?><url><loc><?=htmlspecialchars($base.'/product.php?slug='.$p['slug'],ENT_XML1)?></loc><lastmod><?=date('Y-m-d',strtotime($p['updated_at']))?></lastmod></url><?php endforeach;?></urlset>